-- Table structure for table `exe_step_jugement`
--

DROP TABLE IF EXISTS `exe_step_jugement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `exe_step_jugement` (
  `id` char(32) NOT NULL COMMENT '主键',
  `exe_step_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '步骤id',
  `sort_order` int DEFAULT '0' COMMENT '判据排序规则',
  `criterion_type` int DEFAULT '0' COMMENT '操作类型。0仅操作，1选值，2录值',
  `criterion_standard` int DEFAULT '0' COMMENT '输入设置，0表示其他，1表示判据关联',
  `criterion_content` varchar(100) DEFAULT NULL COMMENT '值',
  `criterion_value_unit` varchar(100) DEFAULT NULL COMMENT '单位',
  `depend_on_device` int DEFAULT '0' COMMENT '是否使用设备，0表示不用，1表示使用',
  `command_json` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '设备指令备注，具体参考报exe_step_command表',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `description` varchar(200) DEFAULT NULL COMMENT '描述',
  `serial_no` int DEFAULT '1' COMMENT '执行次数',
  `value` varchar(200) DEFAULT NULL COMMENT '最终值',
  `success` int DEFAULT '0' COMMENT '显示成功还是失败,2表示失败，1表示成功,0表示未知',
  PRIMARY KEY (`id`),
  KEY `exe_step_jugement_FK` (`exe_step_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `exe_step_jugement`
--

LOCK TABLES `exe_step_jugement` WRITE;
/*!40000 ALTER TABLE `exe_step_jugement` DISABLE KEYS */;
